entries[31856] = { ["name"] = "Dunkelmond-Karte: Kreuzzug", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nAnlegen: Jedes Mal, wenn Ihr einem Gegner Nahkampf- oder Distanzschaden zufügt, wird Eure Angriffskraft 10 Sek. lang um 0 erhöht. Dieser Effekt ist bis zu 20-mal stapelbar. Jedes Mal, wenn Ihr einen Gegner mit einem Offensivzauber trefft, wird Eure Zaubermacht 10 Sek. lang um 1 erhöht. Dieser Effekt ist bis zu 10-mal stapelbar.\nVerkaufspreis:" }
entries[31857] = { ["name"] = "Dunkelmond-Karte: Zorn", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nAnlegen: Jedes Mal, wenn Eure direkten Schaden verursachenden Angriffe keinen kritischen Treffer erzielen, erhaltet Ihr für die nächsten 10 Sek. 3 kritischen Trefferwert und 3 kritischen Zaubertreffer. Dieser Effekt wird verbraucht, wenn Ihr einen kritischen Treffer erzielt.\nVerkaufspreis:" }
entries[31858] = { ["name"] = "Dunkelmond-Karte: Vergeltung", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Ausdauer\nAnlegen: Wenn Ihr von einem Angriff oder schädlichen Zauber getroffen werdet, besteht eine Chance von 10% bei Eurem Angreifer 2 Heiligschaden zu verursachen. (Procchance: 10%)\nVerkaufspreis:" }
entries[31859] = { ["name"] = "Dunkelmond-Karte: Wahnsinn", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Ausdauer\nAnlegen: Jedes Mal, wenn Ihr einem Gegner einen Todesstoß versetzt, der Erfahrung oder Ehre gewährt, erhaltet Ihr die Macht des Wahnsinns.\nVerkaufspreis:" }
